const STATUS = { discovering: { es: 'Explorando información relacionada en SAP', en: 'Exploring related SAP data' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.discovering[lang] } }];

const data = $('Status Text: Discovering').first().json;
const { organization, session, github_owner, github_repo, github_tag, current_date, language, message } = data;
const integ = organization?.integration || {};
const authDriver = integ.auth_driver || 'b1s';
const connection = authDriver === 'b1s'
  ? { authDriver, baseUrl: integ.base_url, username: session?.user?.username, password: session?.user?.password, companyDB: session?.database }
  : { authDriver, baseUrl: integ.base_url, token: session?.access_token };
const ref = github_tag || 'main';
const chatInput = `Today: ${current_date}. Respond in: ${language}.

Agent: Find has already determined no cataloged process answers this request -- your job is to
find and construct the actual answer yourself, using whatever chain of read-only SAP lookups the
question requires.

CONNECTION (use exactly this for every sap_query_entity_set/sap_entity_get call):
${JSON.stringify(connection)}

GROUNDING:
1. Call get_file_contents with owner=${github_owner}, repo=${github_repo}, path={organization.target}/index.json, ref=${ref}, to see what processes/schemas exist -- this gives you real entity names and field shapes to build from, even though none of these processes alone answers the request. Resolve {organization.target} from the INPUT JSON below. Always call this first.
2. Optionally call get_file_contents once more for one specific schema file, at path={organization.target}/<the schema's own path from the index or from a relations entry>.json (same owner/repo/ref, same {organization.target} prefix as step 1 -- some schema slugs exist under more than one family/target with the same name, e.g. a b1s and an odata version of the same entity; always stay within the current {organization.target}, never guess a different family's version), whose entity is closest to the question, to read its \`fields\` and, when present, its \`relations\` array (a list of {entity, schema, direction, description} describing how it links to other entities) -- use \`relations\` as a hint for which other entity to query next, when it exists. At most 2 GitHub MCP calls total this turn.

OData v2 FILTER SYNTAX RULES (SAP B1S):
- String contains: substringof('value', FieldName) -- NEVER use FieldName contains 'value'
- String equals: FieldName eq 'value'
- Number equals: FieldName eq 123
- Multiple OR: (substringof('a', F) or substringof('b', F))
- AND: expr1 and expr2

USER'S QUESTION: ${message}

INPUT:
\`\`\`json
${JSON.stringify(data, null, 2)}
\`\`\``;
return [{ json: { ...data, sap_connection: connection, chatInput } }];

const base = $json;
const content = base._parsed || {};

// Stateless -- unlike Compute Execution Outcome, there's no intention_nodes entry for this
// turn to mark 'completed' or resume from (SAP: Discovery never creates one), so this node
// only ever needs to classify the agent's own {status, message} into a deliverable outcome.
// active_node_id/intention_nodes pass through completely untouched either way.
if (content.status === 'success') {
  return [{ json: { ...base, message: content.message ?? base.message } }];
}

// Anything else (a graceful 'error' status, or unparseable/unrecognized output) is a genuine
// SAP-side issue Agent: Discover hit mid-chain -- same catch-all precedent as Compute
// Execution Outcome's own else branch.
return [{ json: {
  ...base,
  message: content.message ?? base.message,
  _needs_error_parse: true,
  error: 'SAP_ERROR',
  error_message: content.message || null,
} }];
